'use client';

import Link from 'next/link';
import { FormEvent, useEffect, useState } from 'react';
import { ApiClientError, contactVendor, getVendorPage, PrinterListing, VendorProfile } from '../../lib/api-client';

export function PublicVendorPage({ slug }: { slug: string }) {
  const [data, setData] = useState<{ vendor: VendorProfile; printers: PrinterListing[] }>(); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [phone, setPhone] = useState(''); const [status, setStatus] = useState('');
  useEffect(() => { getVendorPage(slug).then(setData).catch((e) => setError(e instanceof ApiClientError ? e.message : 'Vendor page unavailable.')); }, [slug]);
  async function submit(event: FormEvent) { event.preventDefault(); setStatus('Sending…'); try { await contactVendor(slug, { message, phone }); setMessage(''); setPhone(''); setStatus('Message sent. The vendor can now reply to you.'); } catch (e) { setStatus(e instanceof ApiClientError ? e.message : 'Please sign in as a customer to contact this vendor.'); } }
  if (error) return <main className="public-vendor"><Link href="/" className="back">← 3oD home</Link><h1>{error}</h1></main>;
  if (!data) return <main className="public-vendor"><p>Loading workshop…</p></main>;
  return <main className="public-vendor"><Link href="/" className="back">← 3oD home</Link><header><p className="eyebrow">3oD WORKSHOP PAGE</p><h1>{data.vendor.businessName}</h1><p className="location">{[data.vendor.city, data.vendor.state].filter(Boolean).join(', ') || 'India'} · Open for enquiries</p><p className="bio">{data.vendor.bio || 'A local maker ready to bring your designs to life.'}</p></header><section className="public-layout"><div><p className="eyebrow">AVAILABLE MACHINES</p><div className="printer-list">{data.printers.map((printer) => <article className="printer" key={printer.id}><div><h2>{printer.name}</h2><p>{printer.model || 'Custom 3D printing service'}</p><small>{printer.technologies.join(' · ') || '3D printing'} {printer.materials.length ? `· ${printer.materials.join(', ')}` : ''}</small></div><strong>MOQ {printer.minOrderQuantity} {printer.minOrderQuantity === 1 ? 'part' : 'parts'}</strong></article>)}</div></div><form className="contact" onSubmit={submit}><p className="eyebrow">START A CONVERSATION</p><h2>Have a part in mind?</h2><p>Share what you need and ask about cost, lead time, or material.</p><textarea required minLength={5} value={message} onChange={(e) => setMessage(e.target.value)} placeholder="I need 25 PETG brackets…" /><input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="Phone number (optional)" /><button type="submit">Contact this vendor →</button>{status && <small className="form-status">{status}</small>}</form></section><style jsx>{`.public-vendor{min-height:100vh;background:#f7f8f3;color:#20221e;padding:32px max(20px,calc((100vw - 1080px)/2));font-family:Arial,sans-serif}.back{font-size:13px;color:#72766d;text-decoration:none}.public-vendor header{padding:80px 0 54px;max-width:710px}.eyebrow{font-size:10px;letter-spacing:.15em;font-weight:700;color:#ef6847}.public-vendor h1{font-size:clamp(42px,7vw,78px);line-height:.95;letter-spacing:-.07em;margin:18px 0}.location{color:#ef6847;font-size:13px}.bio{font-size:18px;line-height:1.5;color:#72766d;margin-top:24px}.public-layout{display:grid;grid-template-columns:1.2fr .8fr;gap:50px}.printer-list{margin-top:18px;border-top:1px solid #dedfd8}.printer{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:22px 0;border-bottom:1px solid #dedfd8}.printer h2,.contact h2{font-size:21px;letter-spacing:-.04em;margin:0 0 7px}.printer p,.printer small,.contact>p{color:#7b7f76;font-size:12px;margin:0}.printer small{display:block;margin-top:8px}.printer strong{white-space:nowrap;color:#277b60;font-size:12px;background:#e5f3ea;padding:8px 10px;border-radius:20px}.contact{background:#20221e;color:white;border-radius:12px;padding:26px;display:grid;gap:14px;height:max-content}.contact .eyebrow{color:#ffac91}.contact h2{font-size:28px}.contact>p{color:#bfc3b9;line-height:1.5}.contact textarea,.contact input{width:100%;border:1px solid #4b4f47;background:#2a2d28;color:white;border-radius:6px;padding:12px;font:inherit;font-size:13px}.contact textarea{min-height:130px;resize:vertical}.contact button{border:0;border-radius:6px;background:#ef6847;color:white;padding:14px;font-weight:700;cursor:pointer}.form-status{color:#9ee0bc;font-size:12px}@media(max-width:760px){.public-layout{grid-template-columns:1fr}.public-vendor header{padding-top:55px}.printer{align-items:flex-start;flex-direction:column}.contact{margin-top:10px}}`}</style></main>;
}
